insert into hab_normas (id, codigo, nombre, url_fuente, url_compilada, fecha_consulta, vigente_desde, vigente_hasta, notas) values
  ('66cba8a9-8597-53d6-94a8-5fdacb81ba7d', 'RES3100_2019_COMPILADA_2026-10', 'Resolución 3100 de 2019 (MinSalud) — Manual de Inscripción de Prestadores y Habilitación de Servicios de Salud, con sus modificaciones vigentes (compilación consultada el 2026-10-06)', 'https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/DE/DIJ/resolucion-3100-de-2019.pdf', 'https://normograma.supersalud.gov.co/compilacion/docs/resolucion_minsaludps_3100_2019.htm', '2026-10-06', '2019-11-26', null, 'Texto de 2019 cotejado con la compilación de Supersalud. Incluye Res. 2215/2020, 1317/2021, 1138/2022, 1410/2022 (11.3.7), 1719/2022, 544/2023, 648/2023, 465/2025 y 914/2025 (vigencias desde 2027-01-03). La Res. 1732/2026 nunca surtió efectos y fue revocada por la Res. 2080/2026.')
insert into hab_estandares (codigo, sigla, nombre, numeral_manual, definicion_literal, pagina, orden) values
  ('talento_humano', 'TH', 'Talento humano', '8.3.1.1', 'Son las condiciones de talento humano requeridas para la prestación de los servicios de salud. El estándar de talento humano define el perfil o los perfiles mínimos, según aplique, que se deben garantizar para la habilitación y prestación del respectivo servicio de salud.', 36, 1),
  ('infraestructura', 'IN', 'Infraestructura', '8.3.1.2', 'Son las condiciones mínimas e indispensables de las áreas y ambientes de una edificación y su mantenimiento, para la prestación de los servicios de salud con el menor riesgo posible.', 36, 2),
  ('dotacion', 'DO', 'Dotación', '8.3.1.3', 'Son las condiciones mínimas e indispensables que garantizan los equipos biomédicos necesarios, así como sus mantenimientos, para la prestación de los servicios de salud con el menor riesgo posible.', 36, 3),
  ('medicamentos_dispositivos_insumos', 'MD', 'Medicamentos, dispositivos médicos e insumos', '8.3.1.4', 'Son las condiciones mínimas e indispensables de procesos que garantizan las condiciones de almacenamiento, trazabilidad, y seguimiento al uso de medicamentos, componentes anatómicos, dispositivos médicos, reactivos de diagnóstico in vitro; así como de los demás insumos asistenciales que utilice el prestador para la prestación de los servicios de salud con el menor riesgo posible.', 36, 4),
  ('procesos_prioritarios', 'PP', 'Procesos prioritarios', '8.3.1.5', 'Es la existencia obligatoria y socialización de los principales procesos asistenciales que condicionan directamente la prestación con el menor riesgo posible en los servicios de salud.', 36, 5),
  ('historia_clinica_registros', 'HC', 'Historia clínica y registros', '8.3.1.6', 'Son las condiciones mínimas e indispensables que debe cumplir la historia clínica y los registros asistenciales, con el fin de garantizar la trazabilidad de la atención en salud.', 36, 6),
  ('interdependencia', 'IT', 'Interdependencia', '8.3.1.7', 'En este estándar se definen los servicios de salud y de apoyo los cuales son indispensables para prestar en forma oportuna y segura el servicio de salud que los requiere.
