insert into hab_mapeo_practica_servicio (practica_medica_id, servicio_norma_id, requiere_eleccion, nota, confianza) values
  ('e02fe4a9-da69-463c-8036-125cb0670197', '7977d8b4-60a2-5417-b3ec-48cc51a839ba', false, 'Consulta por profesional de la salud no especialista (TH 11.2.1 crit. 2: ''profesional de la salud de acuerdo con el servicio a ofertar''). La dotación 11.2.1 cita expresamente ''consulta externa de medicina general''.', 'alta'),
  ('66f0e259-bda1-4da2-a2ec-ed1862310cad', '7977d8b4-60a2-5417-b3ec-48cc51a839ba', false, 'Profesional de la salud no especialista → consulta externa general. La Res. 3100 no enumera profesiones por servicio; inferido de TH 11.2.1 vs 11.2.2.', 'inferida'),
  ('197b86a8-bbfc-4db8-9dd2-99af9bd2e7db', '7977d8b4-60a2-5417-b3ec-48cc51a839ba', false, '11.2.1 incluye ''consultorio odontológico'' en infraestructura y dotación.', 'alta'),
  ('7d80642f-4ddc-4696-86bd-98b2d995c32c', '7977d8b4-60a2-5417-b3ec-48cc51a839ba', false, 'Profesional no especialista → consulta externa general (inferido; la norma no lista profesiones).', 'inferida'),
  ('8b636bd9-e1c3-4689-81be-b2ca766ed41d', '7977d8b4-60a2-5417-b3ec-48cc51a839ba', false, 'Profesional no especialista → consulta externa general (inferido). Si es psiquiatría o psicología especializada sería 11.2.2.', 'inferida'),
  ('92801779-5797-415c-b2d4-0940d3f961c4', '7977d8b4-60a2-5417-b3ec-48cc51a839ba', false, 'Profesional no especialista → consulta externa general (inferido).', 'inferida'),
  ('ca345094-484f-4862-abfa-bee60fe80288', 'bf77b3ec-cd9d-5c57-897c-c2073c2af6e6', false, 'El usuario lo cargó en Consulta Externa, pero la Res. 3100 lo ubica en el grupo Apoyo diagnóstico: 11.3.1 ''Incluye: Fisioterapia o terapia física…'' (pág. 94).', 'alta'),
  ('b1a73f46-6a9a-4969-b9f8-b002cb8a3466', 'bf77b3ec-cd9d-5c57-897c-c2073c2af6e6', false, '11.3.1 incluye ''fonoaudiología o terapia del lenguaje''. Grupo distinto al que cargó el usuario.', 'alta'),
  ('98b32dcc-2710-450d-a680-90fd025fbce6', 'bf77b3ec-cd9d-5c57-897c-c2073c2af6e6', false, '11.3.1 incluye ''terapia ocupacional''. Grupo distinto al que cargó el usuario.', 'alta'),
  ('98fb0ad4-fa98-40e8-8ed0-3b9a3f3aa75e', 'bf77b3ec-cd9d-5c57-897c-c2073c2af6e6', false, '11.3.1 incluye ''terapia respiratoria''. Grupo distinto al que cargó el usuario.', 'alta'),
  ('2539d29d-68d6-4012-a09a-7efcc6ffbe39', '2a4aa343-f714-5dd7-bc8e-fc62e034da8d', false, null, 'alta'),
