  ('9e3cc4a3-2aa9-460e-b6c5-dac0de69bf15', 'e5f7a0bf-6662-5175-9c24-2bd79378f51b', false, 'Consulta externa especializada (TH exige profesional especialista).', 'alta'),
  ('0bfc65b5-ee56-49ab-8b3a-bceb76fa5800', 'e5f7a0bf-6662-5175-9c24-2bd79378f51b', false, 'Solo la CONSULTA de especialidades quirúrgicas. Si además opera, aplica 11.5.1 Cirugía.', 'alta'),
