-- Aserciones finales de conteo

do $$
declare
  v int;
begin
  select count(*) into v from hab_normas where id = '66cba8a9-8597-53d6-94a8-5fdacb81ba7d';
  if v <> 1 then
    raise exception 'Seed de habilitación: hab_normas tiene % filas y se esperaban 1', v;
  end if;
  select count(*) into v from hab_servicios_norma where norma_id = '66cba8a9-8597-53d6-94a8-5fdacb81ba7d';
  if v <> 42 then
    raise exception 'Seed de habilitación: hab_servicios_norma tiene % filas y se esperaban 42', v;
  end if;
  select count(*) into v from hab_bloques where servicio_norma_id in (select id from hab_servicios_norma where norma_id = '66cba8a9-8597-53d6-94a8-5fdacb81ba7d');
  if v <> 708 then
    raise exception 'Seed de habilitación: hab_bloques tiene % filas y se esperaban 708', v;
  end if;
  select count(*) into v from hab_criterios where norma_id = '66cba8a9-8597-53d6-94a8-5fdacb81ba7d';
  if v <> 3976 then
    raise exception 'Seed de habilitación: hab_criterios tiene % filas y se esperaban 3976', v;
  end if;
  select count(*) into v from hab_criterios where norma_id = '66cba8a9-8597-53d6-94a8-5fdacb81ba7d' and remite_a_11_1;
  if v <> 481 then
    raise exception 'Seed de habilitación: hab_criterios tiene % filas y se esperaban 481', v;
  end if;
  select count(*) into v from hab_criterios where norma_id = '66cba8a9-8597-53d6-94a8-5fdacb81ba7d' and vigente_hasta is not null;
  if v <> 45 then
    raise exception 'Seed de habilitación: hab_criterios tiene % filas y se esperaban 45', v;
  end if;
  select count(*) into v from hab_criterio_remisiones where criterio_id in (select id from hab_criterios where norma_id = '66cba8a9-8597-53d6-94a8-5fdacb81ba7d');
  if v <> 68 then
    raise exception 'Seed de habilitación: hab_criterio_remisiones tiene % filas y se esperaban 68', v;
  end if;
  select count(*) into v from hab_mapeo_practica_servicio where servicio_norma_id in (select id from hab_servicios_norma where norma_id = '66cba8a9-8597-53d6-94a8-5fdacb81ba7d');
  if v <> 62 then
    raise exception 'Seed de habilitación: hab_mapeo_practica_servicio tiene % filas y se esperaban 62', v;
  end if;
end;
